import java.io.*;
import java.util.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int v) { val = v; }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().trim().split("\\s+");
        int insertVal = Integer.parseInt(br.readLine().trim());

        TreeNode root = buildTree(parts);
        root = insertIntoBST(root, insertVal);

        List<String> result = levelOrder(root);
        System.out.println(String.join(" ", result));
    }

    static TreeNode buildTree(String[] parts) {
        if (parts.length == 0 || "null".equals(parts[0])) return null;
        TreeNode root = new TreeNode(Integer.parseInt(parts[0]));
        Queue<TreeNode> q = new LinkedList<>();
        q.offer(root);
        int i = 1;
        while (!q.isEmpty() && i < parts.length) {
            TreeNode node = q.poll();
            if (i < parts.length && !"null".equals(parts[i])) {
                node.left = new TreeNode(Integer.parseInt(parts[i]));
                q.offer(node.left);
            }
            i++;
            if (i < parts.length && !"null".equals(parts[i])) {
                node.right = new TreeNode(Integer.parseInt(parts[i]));
                q.offer(node.right);
            }
            i++;
        }
        return root;
    }

    static TreeNode insertIntoBST(TreeNode root, int val) {
        if (root == null) return new TreeNode(val);
        if (val < root.val) {
            root.left = insertIntoBST(root.left, val);
        } else {
            root.right = insertIntoBST(root.right, val);
        }
        return root;
    }

    static List<String> levelOrder(TreeNode root) {
        List<String> res = new ArrayList<>();
        if (root == null) {
            res.add("null");
            return res;
        }
        Queue<TreeNode> q = new LinkedList<>();
        q.offer(root);
        boolean hasNonNull = true;
        while (hasNonNull) {
            hasNonNull = false;
            int size = q.size();
            for (int i = 0; i < size; i++) {
                TreeNode node = q.poll();
                if (node == null) {
                    res.add("null");
                    q.offer(null);
                    q.offer(null);
                } else {
                    res.add(String.valueOf(node.val));
                    if (node.left != null || node.right != null) hasNonNull = true;
                    q.offer(node.left);
                    q.offer(node.right);
                }
            }
        }
        // Remove trailing nulls
        int lastNonNull = -1;
        for (int i = res.size() - 1; i >= 0; i--) {
            if (!"null".equals(res.get(i))) {
                lastNonNull = i;
                break;
            }
        }
        if (lastNonNull == -1) return Arrays.asList("null");
        return new ArrayList<>(res.subList(0, lastNonNull + 1));
    }
}
